#include "control_plane.hpp"
namespace exotic::runtime {ControlPlane::ControlPlane(TelemetryRepository&r,std::string w):repo_(r),workspace_id_(std::move(w)){}void ControlPlane::set(std::string k,std::string v,std::string a,std::string r){repo_.set_control({workspace_id_,std::move(k),std::move(v),std::move(a),std::move(r),Clock::now()});}void ControlPlane::request_shutdown(std::string a,std::string r){set("shutdown","requested",std::move(a),std::move(r));}void ControlPlane::request_emergency_stop(std::string a,std::string r){set("emergency","activate",std::move(a),std::move(r));}void ControlPlane::request_emergency_clear(std::string a,std::string r){set("emergency","clear",std::move(a),std::move(r));}bool ControlPlane::shutdown_requested(){auto c=repo_.get_control("shutdown");return c&&c->value=="requested";}std::optional<ControlRecord>ControlPlane::emergency_request(){auto c=repo_.get_control("emergency");if(c&&(c->value=="activate"||c->value=="clear"))return c;return std::nullopt;}void ControlPlane::clear_command(std::string_view k){set(std::string{k},"clear","runtime","processed");}}
